{
  "headline": "FDA's records trace our supply to plants with multiple OAI inspections and Warning Letters before the shortage posting",
  "headline_cites": ["E21", "E9", "E11", "E20", "E13", "E15", "E35", "E24", "E25", "E27", "E34"],
  "sentences": [
    {
      "text": "The FDA first posted the atropine sulfate shortage on 2012-01-01 and it has remained current for 178 months as of 2026-10-21.",
      "cites": ["E51", "E18"]
    },
    {
      "text": "Our Corvale General supply includes product labeled by Hospira, Inc. (FEI 1021343) and Amneal Pharmaceuticals NY LLC (FEI 3010254278).",
      "cites": ["E4", "E5", "E21", "E41"]
    },
    {
      "text": "FDA records show Hospira's plant received OAI classifications on 2010-01-19 (712 days before posting), 2011-06-17 (198 days before), and 2011-08-04 (150 days before), plus Warning Letters on 2010-04-12 (629 days before) and 2011-08-31 (123 days before).",
      "cites": ["E11", "E13", "E15", "E20", "E12", "D6", "D10", "D11", "D7", "D12"]
    },
    {
      "text": "American Regent's plant (FEI 2410375) received an OAI classification on 2011-03-15 (292 days before posting) and a Warning Letter on 2011-08-31 (123 days before posting).",
      "cites": ["E27", "E34", "D9", "D12"]
    },
    {
      "text": "The FDA shortage list shows Hospira, Inc. cites manufacturing delay with next delivery estimated December 2026, while American Regent, Inc. remains current without a recovery date.",
      "cites": ["E48", "E44"]
    },
    {
      "text": "Corvale East has 8.9 days on hand and Corvale General has 16 days on hand, making a transfer of 20 units from General to East the top-ranked option to extend East to 11 days while General retains two weeks.",
      "cites": ["D1", "D2", "D15"]
    }
  ]
}
